// The data behind the Zenarios station: the real Zenarios engine's output for the app's built-in
// example household (the Beckers), generated by `scripts/gen/zenarios.mjs` and committed:
// a month-by-month forecast, 1,000 simulated market futures, and the household's life events.
//
// Values are display units 0…1 (asinh-compressed euros, see the generator), so the thread only
// has to place them. The file is fetched beside the thread's code, not bundled into it.

import dataUrl from "../../generated/zenarios-thread.json?url";

interface ThreadFile {
  startYear: number;
  years: number;
  months: number;
  trials: number;
  endP10: number;
  endP90: number;
  forecast: number[];
  forecastYearly: number[];
  medianYearly: number[];
  /** Base64 u8, trial-major, trials × (years + 1). */
  fan: string;
  /** Base64 u8, final-value percentile of each stored trial. */
  percentile: string;
  milestones: { id: string; index: number }[];
}

export interface ZenariosData {
  startYear: number;
  /** Year-end samples per future (years + 1 with today). */
  years: number;
  /** Months in the forecast. */
  months: number;
  /** Net worth per month, display units. */
  forecast: Float32Array;
  /** Per year, years + 1 values, display units. */
  forecastYearly: Float32Array;
  medianYearly: Float32Array;
  /** Trial-major display values, trials × (years + 1), in stratified order. */
  fan: Float32Array;
  trials: number;
  /** Final-value percentile of each stored trial, 0…1. */
  percentile: Float32Array;
  /** Where the best and worst 10 % of futures end, display units. */
  endP10: number;
  endP90: number;
  /** The household's life events: where each falls along the chart (0…1). */
  milestones: Map<string, number>;
}

const bytes = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export async function loadZenarios(): Promise<ZenariosData> {
  const file: ThreadFile = await (await fetch(dataUrl)).json();
  const fan = new Float32Array(bytes(file.fan)).map((v) => v / 255);
  const percentile = new Float32Array(bytes(file.percentile)).map((v) => v / 255);
  return {
    startYear: file.startYear,
    years: file.years,
    months: file.months,
    forecast: Float32Array.from(file.forecast),
    forecastYearly: Float32Array.from(file.forecastYearly),
    medianYearly: Float32Array.from(file.medianYearly),
    fan,
    trials: file.trials,
    percentile,
    endP10: file.endP10,
    endP90: file.endP90,
    milestones: new Map(file.milestones.map((m) => [m.id, m.index / (file.months - 1)])),
  };
}
